/* Cinematic Living Nexus Proof 06. Image is owner-approved composition; this
   independent controller does not replace the tested PR #11 production app. */
(()=>{'use strict';
const $=id=>document.getElementById(id),stage=$('stage'),viewport=$('viewport'),app=$('app'),panel=$('panel'),body=$('panelBody'),actions=$('panelActions'),status=$('statusline');
const base='https://headless-mfewrcffiie-archonsoulings-140e.wix-site-host.com/';
const worlds={
 aura:{title:'Aura Dynamics',subtitle:'The Living Field',description:'Explore the existing Aura Dynamics exercises: Sense, Shape, Expand, Connect and Integrate.',url:'aura-dynamics.html',x:768,y:158,color:'#9bedd9'},
 aureglossa:{title:'Aureglossa',subtitle:'The Living Tongue',description:'Explore the canonical language, its roots, meanings, and developing luminous relationships.',url:'living-tongue.html',x:440,y:312,color:'#9ab7f8'},
 sessions:{title:'Sessions',subtitle:'The Inner Sanctum',description:'Explore Archon Soulings services and pathways to work together.',url:'inner-sanctum.html',x:1096,y:310,color:'#f4d9ab'},
 workshops:{title:'Workshops',subtitle:'The Convergence',description:'Discover gatherings, workshops, teaching, and collaborative experiences.',url:'convergence.html',x:438,y:631,color:'#f6c78f'},
 gestalt:{title:'Gestalt',subtitle:'The Living Archive',description:'Explore the public Gestalt Seed / Soul & Stone archive and its documented relationships.',url:'living-archive.html',x:1092,y:630,color:'#c2a2f4'},
 journal:{title:'Journal / Stories',subtitle:'The Astral Archive',description:'Explore field notes, creative writing, and public stories.',url:'astral-journal.html',x:768,y:756,color:'#a5a3f3'},
 nexus:{title:'Nexus',subtitle:'The Meeting Field',description:'Six paths. One living field. Choose what to explore, or let Guide Me illuminate a path.',url:null,x:768,y:475,color:'#ffe5b5'}
};
const state={selected:null,focus:null,still:matchMedia('(prefers-reduced-motion:reduce)').matches,thread:[],saved:false,scale:1,zoom:1,panX:0,panY:0,tiltX:0,tiltY:0,dragging:false,gaze:null};
const WORLD_IDS=Object.keys(worlds).filter(x=>x!=='nexus');
// Only a visitor's prior explicit Save may create a resumable public-world path.
try{const saved=JSON.parse(localStorage.getItem('nexus-cinematic-06-saved')||'null');if(saved?.version===1&&Array.isArray(saved.worlds)){state.thread=[...new Set(saved.worlds.filter(id=>WORLD_IDS.includes(id)))].slice(0,6);state.saved=true;}}catch{}
const elWorlds=[...document.querySelectorAll('.world')];
let noticeTimer=0;function announce(s){status.textContent=s;status.classList.add('shown');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>status.classList.remove('shown'),2600);}
function resize(){const w=innerWidth,h=innerHeight;state.scale=Math.max(w/1536,h/1024);applyTransform();}
function applyTransform(){const s=state.scale*state.zoom;const maxX=Math.max(0,(1536*s-innerWidth)/(2*s));const maxY=Math.max(0,(1024*s-innerHeight)/(2*s));state.panX=Math.max(-maxX,Math.min(maxX,state.panX));state.panY=Math.max(-maxY,Math.min(maxY,state.panY));stage.style.setProperty('--stage-scale',s);stage.style.setProperty('--pan-x',state.panX+'px');stage.style.setProperty('--pan-y',state.panY+'px');stage.style.setProperty('--tilt-x',state.tiltX+'deg');stage.style.setProperty('--tilt-y',state.tiltY+'deg');}
function setStill(value,silent=false){state.still=!!value;$('still').setAttribute('aria-pressed',String(state.still));$('still').title=state.still?'Resume decorative motion':'Stop decorative motion';if(!silent)announce(state.still?'Stillness: animation paused; all controls remain available.':'The field is breathing again.');window.dispatchEvent(new Event('nexus:motion'));}
function openPanel(title,subtitle,description){panel.classList.remove('hidden');$('panelTitle').textContent=title;$('panelType').textContent=subtitle.toUpperCase();$('panelDescription').textContent=description;body.replaceChildren();actions.replaceChildren();panel.focus({preventScroll:true});}
function addAction(text,handler){const b=document.createElement('button');b.textContent=text;b.addEventListener('click',handler);actions.appendChild(b);return b;}
function closePanel(){panel.classList.add('hidden');app.classList.remove('focused');state.selected=null;state.focus=null;window.dispatchEvent(new Event('nexus:focus'));elWorlds.forEach(x=>x.classList.remove('active'));document.querySelectorAll('.mobile-worlds button').forEach(x=>x.classList.remove('active'));announce('Returned to the Meeting Field.');}
function recordVisit(id){if(id==='nexus')return;if(!state.thread.includes(id))state.thread.push(id);$('threadCount').textContent=state.thread.length;state.saved=false;}
function focusWorld(id,record=true){if(!worlds[id])return;state.selected=id;state.focus=id;app.classList.add('focused');elWorlds.forEach(x=>x.classList.toggle('active',x.dataset.world===id));document.querySelectorAll('.mobile-worlds button').forEach(x=>x.classList.toggle('active',x.dataset.world===id));const w=worlds[id];openPanel(w.title,w.subtitle,w.description);if(record)recordVisit(id);if(w.url){const a=document.createElement('a');a.href=base+w.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Enter '+w.subtitle+' ↗';actions.appendChild(a);if(id==='sessions'){for(const [label,href] of [['Book 30 minutes · $100','https://www.archonsoulings.com/booking-calendar/30-minutes-1'],['Book 60 minutes · $200','https://www.archonsoulings.com/booking-calendar/60-minutes-1']]){const book=document.createElement('a');book.href=href;book.target='_blank';book.rel='noopener noreferrer';book.textContent=label;actions.appendChild(book);}}addAction('Return to Nexus',closePanel);}else addAction('Explore the worlds',()=>{$('guide').click()});announce('The field gathers around '+w.title+'.');window.dispatchEvent(new Event('nexus:focus'));}
function openThread(){openPanel('The Living Thread','YOUR JOURNEY','Your journey reflects the worlds you choose to explore. Save your path on this device, or let it dissolve whenever you wish.');const list=document.createElement('ul');for(const id of state.thread){const li=document.createElement('li');li.textContent=worlds[id].title;list.appendChild(li);}if(!state.thread.length){const p=document.createElement('p');p.textContent='No visited worlds yet. Your journey begins with a choice.';body.appendChild(p);}else body.appendChild(list);addAction('Continue the path',closePanel);addAction('Save this journey',()=>{try{localStorage.setItem('nexus-cinematic-06-saved',JSON.stringify({worlds:state.thread,version:1}));state.saved=true;announce('Your public-world journey was saved on this device.');}catch{announce('Saving is unavailable in this browser.');}});addAction('Let it dissolve',()=>{state.thread=[];state.saved=false;$('threadCount').textContent='0';try{localStorage.removeItem('nexus-cinematic-06-saved');}catch{}closePanel();announce('Your journey has dissolved. Saved local state cleared.');});}
function openGuide(){openPanel('Guide Me','THE FIELD RESPONDS','Choose a world that calls to you. Its luminous path will gently come alive.');const choices=[['Learn something','aura'],['Discover a language','aureglossa'],['Work with someone','sessions'],['Create together','workshops'],['Contribute to an idea','gestalt'],['Explore stories','journal']];for(const [label,id] of choices){const b=document.createElement('button');b.className='choice';b.textContent=label;b.onclick=()=>focusWorld(id,false);body.appendChild(b);}}
async function shareNexus(){const url=location.href;const title='Archon Soulings — The Living Nexus';const text='Explore the Living Nexus and book a session with Archon Soulings.';try{if(navigator.share){await navigator.share({title,text,url});announce('Share sheet opened.');return;}if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(url);announce('Living Nexus link copied.');return;}}catch(e){if(e?.name==='AbortError')return;}announce('Share this link: '+url);}
function openTools(){openPanel('Living Controls','FIELD SETTINGS','Explore with touch, pointer, keyboard, or optional experimental camera-based gaze highlighting.');const label=document.createElement('label');label.textContent='Search worlds';const input=document.createElement('input');input.type='search';input.placeholder='Aura, workshops, language…';input.setAttribute('aria-label','Search worlds');label.appendChild(input);body.appendChild(label);const results=document.createElement('div');body.appendChild(results);input.oninput=()=>{results.replaceChildren();const q=input.value.trim().toLowerCase();for(const id of WORLD_IDS.filter(id=>worlds[id].title.toLowerCase().includes(q)||worlds[id].subtitle.toLowerCase().includes(q)||worlds[id].description.toLowerCase().includes(q)).slice(0,6)){const b=document.createElement('button');b.className='choice';b.textContent=worlds[id].title;b.onclick=()=>focusWorld(id,false);results.appendChild(b);}};input.dispatchEvent(new Event('input'));addAction('Share this Nexus',shareNexus);addAction('Atmosphere (opt-in)',startAtmosphere);addAction('Silence',stopAtmosphere);addAction('Experimental eye tracking',()=>{panel.classList.add('hidden');$('gazePanel').classList.remove('hidden');});addAction('Enable device tilt (optional)',enableDeviceTilt);addAction('Reset view',()=>{state.zoom=1;state.panX=0;state.panY=0;state.tiltX=0;state.tiltY=0;applyTransform();announce('Perspective reset.');});addAction('Return to Nexus',closePanel);}
let orientationActive=false;
async function enableDeviceTilt(){if(!window.DeviceOrientationEvent){announce('Device orientation is not supported. Touch and pointer perspective remain available.');return;}try{if(typeof DeviceOrientationEvent.requestPermission==='function'){const permission=await DeviceOrientationEvent.requestPermission();if(permission!=='granted'){announce('Motion permission was not granted.');return;}}if(!orientationActive){orientationActive=true;window.addEventListener('deviceorientation',e=>{if(document.hidden)return;state.tiltY=Math.max(-3,Math.min(3,(e.gamma||0)*.08));state.tiltX=Math.max(-2.5,Math.min(2.5,(e.beta||0)*.045));applyTransform();});}announce('Motion perspective enabled. Camera and microphone remain off.');}catch{announce('Device motion unavailable. Touch and pointer controls remain available.');}}
let audio=null,osc=[];async function startAtmosphere(){if(audio)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)throw Error('Audio unsupported');audio=new C();await audio.resume();const gain=audio.createGain();gain.gain.value=.008;gain.connect(audio.destination);for(const f of [110,164.81,220]){const o=audio.createOscillator();o.type='sine';o.frequency.value=f;o.connect(gain);o.start();osc.push(o);}announce('Atmosphere on — opt-in resonance. Silence is available in Tools.');}catch{stopAtmosphere();announce('Atmosphere unavailable.');}}
function stopAtmosphere(){for(const o of osc){try{o.stop();o.disconnect();}catch{}}osc=[];if(audio){void audio.close().catch(()=>{});audio=null;}announce('Silence — audio stopped.');}
for(const btn of elWorlds){btn.addEventListener('click',()=>focusWorld(btn.dataset.world));btn.addEventListener('pointerenter',()=>{state.focus=btn.dataset.world;});btn.addEventListener('pointerleave',()=>{if(!state.selected)state.focus=null;});btn.addEventListener('focus',()=>{state.focus=btn.dataset.world;});}
for(const id of WORLD_IDS){const b=document.createElement('button');b.textContent=worlds[id].title;b.onclick=()=>focusWorld(id);$('mobileWorlds').appendChild(b);b.dataset.world=id;}
$('bookNow').addEventListener('click',()=>focusWorld('sessions',false));
$('closePanel').onclick=closePanel;$('still').onclick=()=>setStill(!state.still);$('guide').onclick=openGuide;$('thread').onclick=openThread;$('menu').onclick=openTools;
window.addEventListener('keydown',e=>{if(e.key==='Escape'){closePanel();if(!$('gazePanel').classList.contains('hidden'))$('closeGaze').click();}if(e.key==='+'||e.key==='='){state.zoom=Math.min(2.7,state.zoom*1.12);applyTransform();}if(e.key==='-'){state.zoom=Math.max(.65,state.zoom/1.12);applyTransform();}});
const pointers=new Map();let lastPinch=0;viewport.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});viewport.setPointerCapture(e.pointerId);viewport.classList.add('dragging');});viewport.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId)){if(e.pointerType==='mouse'&&!state.still){state.tiltY=(e.clientX/innerWidth-.5)*3;state.tiltX=-(e.clientY/innerHeight-.5)*2;applyTransform();}return;}const prev=pointers.get(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===1){const s=state.scale*state.zoom;state.panX+=(e.clientX-prev.x)/s;state.panY+=(e.clientY-prev.y)/s;applyTransform();}else if(pointers.size===2){const [a,b]=[...pointers.values()];const d=Math.hypot(a.x-b.x,a.y-b.y);if(lastPinch){state.zoom=Math.max(.65,Math.min(2.7,state.zoom*d/lastPinch));applyTransform();}lastPinch=d;}});const pointerEnd=e=>{pointers.delete(e.pointerId);lastPinch=0;if(!pointers.size)viewport.classList.remove('dragging');};viewport.addEventListener('pointerup',pointerEnd);viewport.addEventListener('pointercancel',pointerEnd);viewport.addEventListener('wheel',e=>{e.preventDefault();state.zoom=Math.max(.65,Math.min(2.7,state.zoom*(e.deltaY>0?.92:1.08)));applyTransform();},{passive:false});
window.addEventListener('resize',resize);document.addEventListener('visibilitychange',()=>{if(document.hidden){stopAtmosphere();window.dispatchEvent(new Event('nexus:motion'));}});window.addEventListener('pagehide',stopAtmosphere);
$('threadCount').textContent=state.thread.length;window.NexusApp={state,worlds,focusWorld,setStill,closePanel,announce,getScreenWorlds:()=>Object.entries(worlds).map(([id,w])=>{const rect=document.querySelector('[data-world="'+id+'"]').getBoundingClientRect();return{id,x:rect.x+rect.width/2,y:rect.y+rect.height/2};})};resize();setStill(state.still,true);
})();
